content.text:
{
  "name": "PM100A光功率计",
  "name_en": "PM100A Optical Power Meter",
  "manufacturer": "Thorlabs",
  "description": "Thorlabs PM100A光功率计，用于测量连续光的光功率，并可设置自动量程和测量参考波长以适配不同光源。常用于激光、光纤和通用光学实验中的功率监测与校准。",
  "description_en": "The Thorlabs PM100A is an optical power meter used to measure continuous-wave optical power. It supports automatic ranging and measurement reference wavelength setting for different light sources, and is commonly used for power monitoring and calibration in laser, fiber-optic, and general photonics experiments.",
  "actions": [
    {
      "action_name": "auto-identify",
      "description": "查询设备身份信息。",
      "description_en": "Query the instrument identification information."
    },
    {
      "action_name": "auto-measure",
      "description": "测量当前光功率。",
      "description_en": "Measure the current optical power."
    },
    {
      "action_name": "auto-setAutoRange",
      "description": "启用自动量程。",
      "description_en": "Enable automatic measurement range selection."
    },
    {
      "action_name": "auto-setWavelength",
      "description": "设置测量参考波长。",
      "description_en": "Set the reference wavelength used for optical power measurement."
    },
    {
      "action_name": "auto-auto_range",
      "description": "设置自动量程功能。",
      "description_en": "Set the automatic ranging function."
    },
    {
      "action_name": "auto-set_wavelength",
      "description": "设置测量参考波长。",
      "description_en": "Set the reference wavelength for measurement."
    }
  ],
  "tag_hints": [
    "optical power measurement",
    "laser power monitoring",
    "photonics instrumentation",
    "wavelength compensation",
    "auto ranging",
    "GPIB control"
  ]
}

